INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-director-de-la-orquesta-scout', 'El Director de la Orquesta Scout', 'Dinámica de atención visual y perspicacia rítmica donde un scout debe descubrir quién lidera las señales de la orquesta.', '<h2>📜 Descripción de El Director de la Orquesta Scout</h2>
<p><b>El Director de la Orquesta Scout</b> es una dinámica de observación sutil, sincronización rítmica y camuflaje grupal. Organizados en círculo, todos los scouts eligen en secreto a un participante para que actúe como el ''Director de Orquesta''. Un observador sale previamente del recinto y luego se ubica en el centro. El Director inicia movimientos musicales o rítmicos marcados (ej. <i>''Tocar violín''</i>, <i>''Dar dos palmas''</i> o <i>''Tocar la batería''</i>), los cuales son imitados inmediatamente por todo el grupo. El buscador dispone de tres oportunidades para descubrir quién es el auténtico Director antes de que el ritmo cambie.</p>
<p>Esta actividad ejercita la visión periférica, la atención a los detalles y la complicidad fraterna en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega El Director de la Orquesta Scout?</h2>
<p>Para llevar a cabo la dinámica con dinamismo y entusiasmo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Formación en Círculo:</b> La unidad se sienta en círculo; un scout sale unos metros sin mirar ni escuchar.</li>
  <li><b>Elección del Director:</b> El grupo señala en silencio al participante que liderará los ritmos de la orquesta.</li>
  <li><b>Entrada del Observador:</b> El scout regresa al centro y la orquesta comienza a ejecutar el primer instrumento asignado.</li>
  <li><b>Cambio Discreto de Ritmo:</b> El Director cambia suavemente de movimiento sin mirar fijamente a nadie, y el grupo lo imita al unísono.</li>
  <li><b>Adivinación y Rotación:</b> Si el observador descubre al Director, este último pasa al centro para la siguiente ronda.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Director de la Orquesta Scout</h2>
<p>La actividad valora la perspicacia y la sincronía en el Tally:</p>
<ul>
  <li><b>Descubrimiento Veloz:</b> Otorgar 5 puntos al observador que identifique al Director en su primer intento.</li>
  <li><b>Camuflaje Impecable:</b> Otorgar 3 puntos a la patrulla que cambie de ritmo 5 veces consecutivas sin ser detectada.</li>
  <li><b>Sincronía Ritmo-Colectiva:</b> Otorgar 3 puntos a la unidad que imite las señas de forma instantánea.</li>
</ul>', '/uploads/el-director-de-la-orquesta-scout.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Sin Materiales"], "objetivos": ["Estimular la observación", "Estimular la atención a los detalles", "Estimular la capacidad de reacción", "Crear un ambiente de distensión"], "justificacion_areas": "El Director de la Orquesta Scout potencia la creatividad al requerir la invención de patrones rítmicos gestuales y la lectura sutil de la expresión corporal. Desarrolla la sociabilidad al afianzar la empatía colectiva, la visión periférica y el juego coordinado sin fisuras desde Manada hasta Clan.", "variaciones": "<b>Orquesta Sonora con Instrumentos de Percusión:</b> Ejecutar los cambios utilizando ruidos corporales (chasquidos, pisadas).<br><b>Orquesta de Movimientos Scout:</b> Utilizar señas de semáforo o nudos dramatizados.<br><b>Director Doble:</b> Designar a dos directores que deben sincronizarse mutuamente.", "recomendaciones": "Pedir a los participantes que eviten mirar fijamente al Director para no delatar su posición. Mantener una atmósfera de risa y complicidad.", "objetivos_educativos": [{"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando atentamente la visión periférica del grupo para descubrir al director de la orquesta."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Imitando rítmicamente las seña del director sin delatar su ubicación."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando las normas de sigilo y sincronía durante el juego."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Colaborando fraternalmente para mantener la complicidad de la Manada."}, {"id": "12686e7d-d6af-4c74-928d-c859d5b883d5", "area": "Creatividad", "unidad": "Compañía", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "como_se_cumple": "Proponiendo secuencias rítmicas disimuladas en el equipo."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Analizando las miradas y la atención dispersa de las compañeras en el círculo."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Manteniendo el clima de risa respetuosa e integración mutua."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Fomentando el trabajo cooperativo y la empatía en la ronda."}, {"id": "e465926e-deed-4341-956f-047f56860e5e", "area": "Creatividad", "unidad": "Tropa", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "como_se_cumple": "Coordinando la soltura y velocidad de respuesta rítmica en la Tropa."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Descifrando patrones de imitación mediante deducción periférica."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Demostrando juego limpio y aceptación alegre de los roles asignados."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y el apoyo entre patrullas."}, {"id": "ed17d59c-1c64-4080-a206-bbe72eeae5a4", "area": "Creatividad", "unidad": "Avanzada", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Liderando la animación rítmica y la distensión en la Avanzada."}, {"id": "3fd19eb4-737c-43c5-9ea8-5e5307ce0309", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Promoviendo el respeto y la inclusión sutil en actividades de grupo."}, {"id": "ef75fbed-4a6d-49ea-bfab-f2952415e1a0", "area": "Creatividad", "unidad": "Clan", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Demostrando agilidad mental y liderazgo de grupo en desafíos de observación Rover."}, {"id": "b5954f1c-4d0d-4bdb-97d8-821583beb77e", "area": "Sociabilidad", "unidad": "Clan", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Viviendo la fraternidad scout y el servicio alegre en el Clan."}]}'::jsonb, NOW(), NOW(), NULL, NULL
